#pragma once
#include "app.hpp"
#include <string>
#include <vector>
namespace coop {
// A shared Scoop .shim records only the target path and optional arguments. Unknown keys do not
// make the entry unusable, because Scoop may add metadata; they are simply not interpreted.
struct ShimMetadata {
    std::string target;
    std::string arguments;
};
ShimMetadata read_shim_metadata(const fs::path& path);
// Scoop's shim executables are generated by one of its shim implementations. The exact digest is
// not a stable API (GUI patching and Scoop releases change it), so recognize the shim program by
// its PE format and embedded shim markers instead of a fixed digest allowlist.
bool looks_like_scoop_shim(const fs::path& path);
// A copied coop launcher reads its .coop-shim.json (or adjacent Scoop .shim) metadata and forwards
// the call to the declared target with the correct host. Returns false when the running executable
// is not a command launcher.
bool run_shim(int argc, wchar_t** argv, int& result);
// Scoop writes .cmd/.ps1/sh wrappers for script-host entries instead of a .exe/.shim pair. A
// wrapper belongs to a package only when its content points at apps/<package>/; otherwise it is
// left for the client or user that created it.
bool scoop_wrapper_belongs_to_package(const fs::path& path, const std::string& package_name);
// The wrapper also names the declared package-relative target. Two script declarations can share a
// package and alias, so removal checks the target as well as the package identity.
bool scoop_wrapper_names_target(const fs::path& path, const std::string& relative_target);
std::vector<fs::path> scoop_entry_wrappers(const Context& context, const std::string& package_name,
    const std::vector<std::string>& command_names);
}
